head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var a = WebSquare.date.dateTimeAdd("201901", -1, "month");
    alert("201901 - 1 = " + a);
};
scwin.trigger2_onclick = function(e) {
    var a = WebSquare.date.dateTimeAdd("201902", -1, "month");
    alert("201902 - 1 = " + a);
};
scwin.trigger3_onclick = function(e) {
    var a = WebSquare.date.dateTimeAdd("201903", -1, "month");
    localStorage.setItem("log1", "201903 -1 = " + a);
    console.log("201903 -1 = " + a);
};
scwin.trigger4_onclick = function(e) {
    var a = WebSquare.date.dateTimeAdd("201905", -1, "month");
    alert("201905 - 1 = " + a);
};
scwin.unitTest = function() {
        //Unit test
        WebSquare.wUnit.start();
        //Test step 1. 샘플실행 후 trigger3 버튼을 클릭한다.
        WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log1') == '201903 -1 = 201902'", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		// Run test
		WebSquare.wUnit.run();
		// Stop test
		WebSquare.wUnit.stop();
};
scwin.unitTest()
